argv:
$ErrorActionPreference='Stop'
$base='http://127.0.0.1:17448'
Write-Output '=== OPERATOR LIFECYCLE ==='
try {
 $j=Invoke-RestMethod -Uri ($base+'/api/operator-lifecycle') -TimeoutSec 12
 Write-Output ('LIFECYCLE_KEYS='+(@($j.PSObject.Properties.Name) -join ','))
 foreach($k in @('mode','state','status','operatorMode','effectiveMode','canDispatch','dispatchAllowed','reconciliationRequired','running','reason')) {
  if($j.PSObject.Properties.Name -contains $k){Write-Output ($k+'='+[string]$j.$k)}
 }
 if($j.lifecycle){foreach($k in @('mode','state','status','reconciliationRequired')){if($j.lifecycle.PSObject.Properties.Name -contains $k){Write-Output ('lifecycle_'+$k+'='+[string]$j.lifecycle.$k)}}}
} catch { Write-Output ('LIFECYCLE_ERROR='+$_.Exception.Message.Substring(0,[Math]::Min(150,$_.Exception.Message.Length)))}
Write-Output '=== ACTIVE CURRENT ASSIGNMENTS ==='
$a=Invoke-RestMethod -Uri ($base+'/api/supervisor-watchdog/agent-assignments') -TimeoutSec 12
$live=@($a.assignments|Where-Object {$_.state -in @('queued','dispatching','running','awaiting_evidence','unknown')})
Write-Output ('UNSETTLED_COUNT='+$live.Count)
Write-Output ('COUNTS='+($a.counts|ConvertTo-Json -Compress -Depth 2))
Write-Output '=== AGENT MATCHING ==='
$s=Invoke-RestMethod -Uri ($base+'/api/supervisor-watchdog?detect=0') -TimeoutSec 12
$d=Invoke-RestMethod -Uri ($base+'/api/supervisor-watchdog/agent-assignments/dry-run') -TimeoutSec 12
$n=0
foreach($row in @($d.rows)){
 $n++
 $match=@($s.config.managedChats|Where-Object{$_.id -eq $row.chatId})|Select-Object -First 1
 $role=if($match){[string]$match.role}else{'NONE'}
 Write-Output ('AGENT_'+$n+' role='+$role+' preflight='+$row.preflightReason+' allowed='+$row.preflightAllowed+' scheduler='+$row.schedulerSelected+' high='+[bool](@($row.snapshots|Where-Object {$_.highMode}).Count))
}
Write-Output '=== END ==='
